{"content":"class StackUnderflowError(Exception):
    """Raised when an operation needs more items than the stack contains."""


def evaluate(input_data):
    """Evaluate Forth source lines and return the resulting stack.

    Definitions capture the current meanings of words, so redefining a word
    does not change previously compiled definitions.
    """
    stack = []
    arities = {"+": 2, "-": 2, "*": 2, "/": 2,
               "dup": 1, "drop": 1, "swap": 2, "over": 2}
    words = {name: (name,) for name in arities}
    tokens = iter(" ".join(input_data).lower().split())

    def is_number(token):
        return token.isascii() and token.isdigit()

    def resolve(token):
        if is_number(token):
            return (int(token),)
        if token not in words:
            raise ValueError(f"undefined operation: {token}")
        return words[token]

    for token in tokens:
        if token == ":":
            name = next(tokens, None)
            if name is None or name in (":", ";") or is_number(name):
                raise ValueError("invalid word definition: expected a non-numeric name")
            definition = []
            for part in tokens:
                if part == ";":
                    break
                definition.extend(resolve(part))
            else:
                raise ValueError("invalid word definition: missing ';'")
            words[name] = tuple(definition)
            continue

        for operation in resolve(token):
            if isinstance(operation, int):
                stack.append(operation)
                continue
            if len(stack) < arities[operation]:
                raise StackUnderflowError(
                    f"Insufficient number of items in stack for {operation}"
                )
            if operation == "dup":
                stack.append(stack[-1])
            elif operation == "drop":
                stack.pop()
            elif operation == "swap":
                stack[-2], stack[-1] = stack[-1], stack[-2]
            elif operation == "over":
                stack.append(stack[-2])
            else:
                left, right = stack[-2:]
                if operation == "+":
                    result = left + right
                elif operation == "-":
                    result = left - right
                elif operation == "*":
                    result = left * right
                else:
                    if right == 0:
                        raise ZeroDivisionError("divide by zero")
                    # Truncate toward zero without converting to a float.
                    result = abs(left) // abs(right)
                    if (left < 0) != (right < 0):
                        result = -result
                stack[-2:] = [result]

    return stack
