{"content":"import unittest

from forth import StackUnderflowError, evaluate


class ForthTests(unittest.TestCase):
    def test_numbers_and_empty_input(self):
        self.assertEqual(evaluate([]), [])
        self.assertEqual(evaluate(["1 2", "\t003\n65536"]), [1, 2, 3, 65536])

    def test_arithmetic(self):
        cases = {
            "1 2 +": [3],
            "1 2 -": [-1],
            "3 4 *": [12],
            "8 3 /": [2],
            "0 8 - 3 /": [-2],
            "8 0 3 - /": [-2],
            "0 8 - 0 3 - /": [2],
            "1 2 + 4 * 5 -": [7],
        }
        for source, expected in cases.items():
            with self.subTest(source=source):
                self.assertEqual(evaluate([source]), expected)
        large = 10 ** 100
        self.assertEqual(evaluate([f"{large} 3 /"]), [large // 3])

    def test_stack_operations(self):
        cases = {
            "1 DuP": [1, 1],
            "1 2 DROP": [1],
            "1 2 3 swap": [1, 3, 2],
            "1 2 3 OvEr": [1, 2, 3, 2],
        }
        for source, expected in cases.items():
            with self.subTest(source=source):
                self.assertEqual(evaluate([source]), expected)

    def test_stack_underflow(self):
        for word in ("+", "-", "*", "/", "dup", "drop", "swap", "over"):
            inputs = [word]
            if word not in ("dup", "drop"):
                inputs.append("1 " + word)
            for source in inputs:
                with self.subTest(source=source):
                    with self.assertRaisesRegex(StackUnderflowError, "Insufficient"):
                        evaluate([source])

    def test_division_by_zero(self):
        with self.assertRaisesRegex(ZeroDivisionError, "divide by zero"):
            evaluate(["1 0 /"])

    def test_definitions_and_case_insensitivity(self):
        self.assertEqual(evaluate([": Sq DUP * ;", "4 sQ"]), [16])
        self.assertEqual(evaluate([": twice", "dup + ; 3 twice"]), [6])
        self.assertEqual(evaluate([": a 1 ; : b a 2 + ; b"]), [3])
        self.assertEqual(evaluate([": a 1 ; a : a 2 ; a"]), [1, 2])
        self.assertEqual(evaluate([": noop ; 1 noop"]), [1])

    def test_definitions_capture_existing_meanings(self):
        self.assertEqual(evaluate([": foo 5 ; : bar foo ; : foo 6 ; bar foo"]), [5, 6])
        self.assertEqual(evaluate([": foo 5 ; : foo foo 1 + ; foo"]), [6])
        self.assertEqual(evaluate([": double dup + ; : dup 9 ; 4 double dup"]), [8, 9])
        self.assertEqual(evaluate([": + * ; 3 4 +"]), [12])

    def test_word_names_are_not_limited_to_letters(self):
        self.assertEqual(evaluate([": 1a 7 ; : !? 8 ; : -1 9 ; 1a !? -1"]), [7, 8, 9])
        self.assertEqual(evaluate([": ١ 5 ; ١"]), [5])

    def test_invalid_operations_and_definitions(self):
        for source in ("unknown", "١", ": 1 2 ;", ": 001 2 ;", ":", ": ;",
                       ": : 1 ;", ": foo 1", ": foo unknown ;", ": foo foo ;", ";"):
            with self.subTest(source=source):
                with self.assertRaisesRegex(ValueError, ".+"):
                    evaluate([source])

    def test_calls_do_not_share_state(self):
        self.assertEqual(evaluate([": foo 1 ; foo"]), [1])
        self.assertEqual(evaluate([]), [])
        with self.assertRaisesRegex(ValueError, "undefined operation"):
            evaluate(["foo"])


if __name__ == "__main__":
    unittest.main()
